const scenes={empty:'空白会话',answer:'引用回答',agent:'Agent 执行',documents:'文档管理',compare:'论文对比',status:'系统状态'};
const names={empty:'研究工作台',answer:'研究工作台',agent:'研究工作台',documents:'知识库',compare:'论文对比',status:'系统状态'};
const hints={empty:'从一轮论文检索开始。',answer:'Transformer 的效率改进',agent:'比较两种注意力机制',documents:'论文与资料',compare:'两篇论文的结构化字段',status:'服务与索引'};
const composer=`<div class="composer"><textarea aria-label="输入研究问题" placeholder="询问论文、比较方法，或提出你的研究问题…"></textarea><div class="composefoot"><span>添加论文　·　全部知识库</span><button class="send" aria-label="发送问题" data-scene="agent">发送</button></div></div><div class="disclaimer">回答来自 DeepSeek；请核对论文原文。</div>`;
const segment=mode=>`<div class="segmented"><button class="${mode==='rag'?'selected':''}" data-scene="answer">知识库问答</button><button class="${mode==='agent'?'selected':''}" data-scene="agent">智能助理</button></div><div class="modehint">${mode==='rag'?'每次问题独立检索':'多轮会话与工具执行'}</div>`;
const assistant=`<div class="assistanthead">Co-Work <span class="chip">DeepSeek</span></div>`;
const source=`<aside class="inspector"><h2>检查器</h2><div class="tabs"><span class="active">引用来源</span><span>执行过程</span></div><div class="muted" style="margin-bottom:12px">本次回答 · 2 个来源</div><article class="sourcecard"><span class="number">引用 1</span><h3>Efficient Transformers: A Survey</h3><p>2009.06732v3.pdf · 第 4 页</p><blockquote>Efficient attention approaches reduce the memory and computational cost associated with standard self-attention.</blockquote><p>来源片段示意 · 请以真实检索结果为准</p><button data-toast="原型预览：真实应用提供原文件下载">查看原文</button></article><article class="sourcecard"><span class="number">引用 2</span><h3>Transformers are RNNs</h3><p>2006.16236v3.pdf · 第 3 页</p><blockquote>Linear attention expresses attention through kernel feature maps and changes the order of computation.</blockquote><p>来源片段示意 · 请以真实检索结果为准</p><button data-toast="原型预览：真实应用提供原文件下载">查看原文</button></article></aside>`;
const views={
  empty:()=>`<section class="conversationbody">${segment('agent')}<div class="chat"><div class="welcome"><h2>开始一轮论文研究</h2><p>输入一个问题，或从下面的检索任务开始。</p><div class="suggestions"><button data-scene="answer">理解一个研究方向<small>梳理 Transformer 的效率改进</small></button><button data-scene="compare">比较两篇论文<small>从方法、数据集和结果开始</small></button><button data-scene="documents">建立我的知识库<small>上传 PDF、Word 或 Markdown</small></button><button data-scene="agent">查看工具执行<small>了解 Agent 如何完成任务</small></button></div></div></div>${composer}</section>`,
  answer:()=>`<section class="conversationbody">${segment('rag')}<div class="chat"><div class="question"><span>Transformer 有哪些降低注意力计算成本的方法？</span></div>${assistant}<div class="answer"><p>可以从<strong>减少参与计算的连接</strong>和<strong>改变注意力的计算方式</strong>两个角度理解这些方法。</p><h3>稀疏注意力：只关注必要的位置</h3><p>通过局部窗口或稀疏连接，让每个位置只与部分位置交互，减少完整注意力矩阵带来的计算与存储开销。<button class="ref" data-inspect>1</button></p><h3>线性注意力：重新组织计算</h3><p>用核特征映射改写注意力运算，利用矩阵乘法的结合顺序避免显式构造完整矩阵。<button class="ref" data-inspect>2</button></p><h3>选择方法</h3><p>先考虑序列长度和任务对全局信息的需求，再结合论文中的实验条件比较效果。</p></div><div class="answerfoot"><span class="muted">2 个引用 · 4.28 秒 · 演示数据</span><button data-toast="原型：复制回答交互">复制</button></div></div>${composer}</section>${source}`,
  agent:()=>`<section class="conversationbody">${segment('agent')}<div class="chat"><div class="question"><span>比较稀疏注意力与线性注意力的主要差异，并给出论文依据。</span></div>${assistant}<div class="process"><strong>正在整理检索结果</strong><p>知识库检索已完成，正在组织答案。</p></div><div class="answer"><p>已找到相关论文片段。完成分析后，答案和引用会一起显示。</p></div><div class="banner">Agent 最终答案在任务完成后整体呈现。</div></div>${composer}</section><aside class="inspector"><h2>检查器</h2><div class="tabs"><span>引用来源</span><span class="active">执行过程</span></div><div class="muted">本次任务 · 第 2 步</div><div class="timeline"><article class="step"><h3>理解问题</h3><p>识别对比意图与所需证据</p><details open><summary>Thought</summary><p>查找两类方法的原文说明，再按计算方式和适用条件组织对比。</p></details></article><article class="step"><h3>知识库检索</h3><p>hybrid_rerank · 完成</p><details open><summary>Action / Observation</summary><div class="code">knowledge_retrieval<br>top_k: 5</div><p>返回 5 个相关片段<br>RAG 总响应耗时 2.41 秒</p></details></article><article class="step running"><h3>生成最终回答</h3><p>正在整合证据与引用</p></article></div><div class="sourcecard"><h3>执行指标</h3><p>工具调用　1 次<br>Token　未提供<br>状态　进行中</p></div></aside>`,
  documents:()=>`<section class="contentpage"><h2>知识库</h2><p>论文与资料</p><div class="upload"><span class="uploadicon">上传</span><div><h3>将论文拖到这里</h3><p>PDF、DOCX、TXT、Markdown · 每个文件不超过 50MB</p></div><button data-toast="原型预览：实际应用支持批量上传">选择文件</button></div><div class="task"><div class="tasktop"><span>正在向量化 · DeepNet.pdf</span><span>3 / 5 个文件</span></div><div class="progress"><div></div></div></div><div class="sectionhead"><h3>全部文档 <small>5</small></h3><small>演示数据</small></div><table><thead><tr><th>文档名称</th><th>格式 / 大小</th><th>片段数</th><th>状态</th><th></th></tr></thead><tbody><tr><td>Efficient Transformers<small>2009.06732v3.pdf</small></td><td>PDF · 1.8 MB</td><td>86</td><td class="ready">已就绪</td><td><button class="rowaction" data-toast="删除需确认；同时移除索引记录">删除</button></td></tr><tr><td>Transformer in Transformer<small>2103.00112v3.pdf</small></td><td>PDF · 2.4 MB</td><td>54</td><td class="ready">已就绪</td><td><button class="rowaction" data-toast="删除需确认；历史引用快照保留">删除</button></td></tr><tr><td>DeepNet<small>2203.00555v1.pdf</small></td><td>PDF · 1.2 MB</td><td>—</td><td class="pending">向量化中</td><td>—</td></tr><tr><td>Transformers are RNNs<small>2006.16236v3.pdf</small></td><td>PDF · 1.6 MB</td><td>—</td><td class="muted">等待处理</td><td>—</td></tr><tr><td>Research notes<small>notes.pdf</small></td><td>PDF · 340 KB</td><td>—</td><td class="fail">解析失败</td><td><button class="rowaction" data-toast="只重试失败文件">重试</button></td></tr></tbody></table><div class="sectionhead"><h3>论文分析</h3></div><p>选择一篇论文生成摘要，或选择两篇论文进行对比。</p><button data-scene="compare">选择论文并对比</button><div class="bottomnote">上传相同内容会自动跳过；同名但内容不同的文件会独立保存。</div></section>`,
  compare:()=>`<section class="contentpage"><h2>论文对比</h2><p>两篇论文的结构化字段</p><div class="selectrow"><select aria-label="第一篇论文"><option>DeepNet · 2203.00555v1</option><option>Efficient Transformers</option></select><span class="muted">与</span><select aria-label="第二篇论文"><option>Transformer in Transformer · 2103.00112v3</option><option>Transformers are RNNs</option></select><button class="primary" data-toast="原型预览：实际应用传递真实 paper_a / paper_b">对比论文</button></div><div class="banner">未提取到的字段留空，界面不补写研究结论。</div><table class="comparetable"><thead><tr><th>对比维度</th><th>DeepNet</th><th>Transformer in Transformer</th></tr></thead><tbody><tr><td>标题</td><td>DeepNet: Scaling Transformers<br>to 1,000 Layers</td><td>Transformer in Transformer</td></tr><tr><td>论文标识</td><td>2203.00555v1</td><td>2103.00112v3</td></tr><tr><td>方法</td><td class="muted">未提取到</td><td class="muted">未提取到</td></tr><tr><td>实验数据集</td><td class="muted">未提取到</td><td class="muted">未提取到</td></tr><tr><td>实验结果</td><td class="muted">未提取到</td><td class="muted">未提取到</td></tr></tbody></table><div class="sectionhead"><h3>继续研究</h3></div><p>回到工作台，结合论文原文检索证据。</p><button data-scene="answer">在工作台继续研究</button></section>`,
  status:()=>`<section class="contentpage"><h2>系统状态</h2><p>服务与索引</p><div class="statusgrid"><article class="statuscard"><h3>生成服务</h3><div class="statusrow"><span>提供方</span><b>DeepSeek API</b></div><div class="statusrow"><span>API 地址</span><span>api.deepseek.com</span></div><div class="statusrow"><span>模型</span><span>读取 agent.yaml</span></div><div class="statusrow"><span>连接状态</span><span class="pending">已配置，未验证连接</span></div></article><article class="statuscard"><h3>本地知识库</h3><div class="statusrow"><span>检索模式</span><span>混合检索 + 重排序</span></div><div class="statusrow"><span>已就绪文档</span><span>5 篇</span></div><div class="statusrow"><span>索引状态</span><span class="ready">已就绪</span></div><div class="statusrow"><span>联网搜索</span><span class="muted">未启用</span></div></article></div><div class="statusactions"><button class="primary" data-toast="原型预览：检查 DeepSeek 与检索链路">检查连接</button><button data-toast="原型预览：恢复未完成更新">恢复 / 修复知识库</button></div><div class="sectionhead"><h3>运行概览</h3><small>演示数据</small></div><div class="metricrow"><div class="metric"><small>历史请求</small><strong>24 <span>次</span></strong></div><div class="metric"><small>平均总响应耗时</small><strong>4.28 <span>秒</span></strong></div><div class="metric"><small>Token 消耗</small><strong>未提供</strong></div></div><table><thead><tr><th>工具</th><th>调用次数</th><th>成功率</th><th>平均工具耗时</th></tr></thead><tbody><tr><td>知识库检索</td><td>18</td><td>100%</td><td>2.41 秒</td></tr><tr><td>论文对比</td><td>4</td><td>100%</td><td>0.03 秒</td></tr><tr><td>计算器</td><td>2</td><td>100%</td><td>0.01 秒</td></tr></tbody></table><div class="bottomnote">Hit@5 / MRR 尚未评测。</div></section>`
};
function render(){const scene=location.hash.slice(1) in scenes?location.hash.slice(1):'empty';document.getElementById('title').textContent=names[scene];document.getElementById('subtitle').textContent=hints[scene];document.getElementById('scenes').innerHTML=Object.entries(scenes).map(([k,v])=>`<button data-scene="${k}" class="${scene===k?'active':''}">${v}</button>`).join('');document.getElementById('content').innerHTML=views[scene]();document.body.dataset.scene=scene;document.body.classList.remove('hide-inspector');}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.scene){if(location.hash.slice(1)===el.dataset.scene)render();else location.hash=el.dataset.scene;}if(el.id==='toggle')document.body.classList.toggle('hide-inspector');if(el.hasAttribute('data-inspect'))document.body.classList.remove('hide-inspector');if(el.dataset.toast){const toast=document.getElementById('toast');toast.textContent=el.dataset.toast;toast.style.display='block';setTimeout(()=>toast.style.display='none',2600);}});
window.addEventListener('hashchange',render);render();
